mapper.update:
merge into t_gsq_quota_setting a USING (
select #{QuotaSetting.steelRingCode,jdbcType=VARCHAR} steel_ring_code, #{QuotaSetting.machineId,jdbcType=DOUBLE} machine_id, #{QuotaSetting.quota,jdbcType=DOUBLE} quota, #{QuotaSetting.createBy,jdbcType=VARCHAR} create_by, #{QuotaSetting.createTime,jdbcType=DATE} create_time, #{QuotaSetting.updateBy,jdbcType=VARCHAR} update_by, #{QuotaSetting.updateTime,jdbcType=DATE} update_time, #{QuotaSetting.remark,jdbcType=VARCHAR} remark from dual
) b ON ( ((b.steel_ring_code is null and a.steel_ring_code is null) or (a.steel_ring_code = b.steel_ring_code)) and ((b.machine_id is null and a.machine_id is null) or(b.machine_id = a.machine_id)) AND a.del_flag = '0' ) WHEN MATCHED THEN UPDATE SET a.quota = b.quota, a.update_by = b.create_by, a.update_time = sysdate, a.remark = b.remark WHEN NOT MATCHED THEN INSERT (a.id, a.steel_ring_code, a.machine_id, a.quota, a.create_by, a.create_time, a.remark, a.del_flag) values (SEQ_QUOTA_SETTING.NEXTVAL, b.steel_ring_code, b.machine_id, b.quota, b.create_by, sysdate, b.remark, '0')
